function quickselect<T>(arr: T[], k: number, cmp: (a: T, b: T) => number): T {
  // Encontra o k-ésimo menor (0-indexed) em O(n) average
  const a = [...arr];  // cópia para não mutar
  let lo = 0, hi = a.length - 1;
  while (lo < hi) {
    const pivot = a[hi];
    let i = lo;
    for (let j = lo; j < hi; j++) {
      if (cmp(a[j], pivot) < 0) {
        [a[i], a[j]] = [a[j], a[i]];
        i++;
      }
    }
    [a[i], a[hi]] = [a[hi], a[i]];
    if (i === k) return a[i];
    if (i < k) lo = i + 1;
    else hi = i - 1;
  }
  return a[lo];
}

